/*
 * acl_$setids - Apply (or check) an object's set-ID SIDs
 *
 * Original address: 0x00E46B4E, 594 bytes (0x00E46B4E .. 0x00E46D9F); a
 * module-local ACL routine with no map symbol (was FUN_00e46b4e), inside
 * the ACL_ code between ACL_$RIGHTS_CHECK (0xE46AEC) and ACL_$ENTER_SUBS
 * (0xE46DA0).  Callers: ACL_$ENTER_SUBS (0x00E46E7A) and ACL_$SERVER's
 * opcode 0x6A (0x00E497D6).  It is the local counterpart of
 * REM_FILE_$ACL_SETIDS, to which it forwards remote objects.
 * Generated by: Claude Opus 5.5
 *
 * For each of the owner, group and organisation SIDs of `uid`'s protection
 * whose rights byte has bit 5 set (the set-ID bit) and that is not
 * UID_$NIL, and for the required-subsystem UID of its cached ACL image:
 * with `set` TRUE the SID is copied into sids[] (and the owner extension
 * word into owner_ext[]) and *changed becomes TRUE; with `set` FALSE the SID
 * must already equal sids[], else status_$acl_no_right_to_set_subsystem_data.
 * With no cached ACL image sids[3] becomes UID_$NIL.
 *
 * The routine loads no A5 of its own: `(0xb70,A5)` at 0x00E46BCC reads
 * ACL_$UNWIRED_DATA.local_locksmith through the caller's A5, which both
 * callers set to 0xE7CF54.
 *
 * Frame (link.w A6,-0x6c; D2-D6/A2-A4 saved):
 *   (0x08,A6) uid        (A4)      (0x0C,A6) set        byte (D2b)
 *   (0x0E,A6) sids       (A2), four UIDs
 *   (0x12,A6) owner_ext  (D4), three longwords
 *   (0x16,A6) changed    (A3), a Domain boolean
 *   (0x1A,A6) status_ret (D5)
 *   (-0x28,A6) loc     file_$obj_loc_t
 *   (-0x60,A6) attrs   ast_$acl_attr_t; its acl_data at -0x54 is the
 *                      acl_$prot_data_t acl_$find_acl_slot refreshes
 *   (-0x64,A6) status  (-0x6A,A6) cached flag byte
 *   D0w the ACL cache slot (-1 = none), D3b "ACL lock held"
 *
 * Quirks reproduced:
 *   - A failure of acl_$get_obj_acl_attrs is returned with bit 31 set
 *     (0x00E46B88 `bset.b #7,(A0)`).
 *   - Remote objects: after REM_FILE_$ACL_SETIDS, a FALSE `set` that came
 *     back changed stores status_$acl_no_right_to_set_subsystem_data; a
 *     change with the local locksmith word non-zero clears *changed and
 *     puts status_$no_right_to_perform_operation in the local status,
 *     which the exit path at 0x00E46D96 never copies out (dead store).
 *   - The ACL image is looked up even for a UID_$NIL ACL when attrs byte 0
 *     is zero (0x00E46C00-0x00E46C08).
 */

#include "acl/acl_internal.h"
#include "rem_file/rem_file.h"

/* Rights-byte bit 5: the SID is a set-ID SID (0x00E46C3A `btst.b #5`) */
#define ACL_SETIDS_SETID_BIT    0x20

/* No cached image: `moveq #-0x1,D0` at 0x00E46BEA */
#define ACL_SETIDS_NO_SLOT      (-1)

/*
 * One set-ID SID (0x00E46C3A-0x00E46C7E, repeated for group and org).
 * Returns 0 to go on, 1 for a mismatch (status set by the caller).
 */
static int acl_$setids_one(uint8_t rights, const uid_t *prot_sid,
                           uint32_t prot_ext, int8_t set, uid_t *sid,
                           uint32_t *ext, int8_t *changed)
{
    if ((rights & ACL_SETIDS_SETID_BIT) == 0) {
        return 0;
    }
    if (prot_sid->high == UID_$NIL.high && prot_sid->low == UID_$NIL.low) {
        return 0;
    }
    if (set < 0) {
        *changed = (int8_t)0xFF;
        *sid = *prot_sid;
        *ext = prot_ext;
        return 0;
    }
    if (sid->high != prot_sid->high || sid->low != prot_sid->low) {
        return 1;
    }
    return 0;
}

void acl_$setids(uid_t *uid, int8_t set, uid_t *sids, uint32_t *owner_ext,
                 int8_t *changed, status_$t *status_ret)
{
    file_$obj_loc_t loc;           /* (-0x28,A6) */
    ast_$acl_attr_t attrs;         /* (-0x60,A6) */
    status_$t status;              /* (-0x64,A6) */
    int8_t cached;                 /* (-0x6A,A6) */
    int8_t locked;                 /* D3b */
    int16_t slot;                  /* D0w */
    acl_$prot_data_t *prot;
    uid_t req;                     /* (0x12,A0,D1) of the cache slot */

    /* 0x00E46B6E-0x00E46B8C */
    acl_$get_obj_acl_attrs(uid, &loc, &attrs, status_ret);
    if (*status_ret != status_$ok) {
        *status_ret |= (status_$t)0x80000000u;
        return;
    }

    /* 0x00E46B90-0x00E46BDE: a remote object is handled by its node */
    if ((attrs.obj_flags[ACL_ATTR_FLAGS_LO] & ACL_ATTR_FLAG_LOCAL) == 0 &&
        loc.flags < 0) {
        REM_FILE_$ACL_SETIDS(&loc.loc_info, uid, sids, owner_ext, changed,
                             status_ret);
        if ((int8_t)(~(uint8_t)set & (uint8_t)*changed) < 0) {
            *status_ret = status_$acl_no_right_to_set_subsystem_data;
        }
        if (*changed < 0 && ACL_$UNWIRED_DATA.local_locksmith != 0) {
            *changed = 0;
            status = status_$no_right_to_perform_operation;   /* never read */
            (void)status;
        }
        return;
    }

    /* 0x00E46BE2-0x00E46C36 */
    *changed = 0;
    locked = 0;
    status = status_$ok;
    slot = ACL_SETIDS_NO_SLOT;
    prot = ACL_$PROT_DATA(&attrs);
    if (!(attrs.default_acl.high == UID_$NIL.high &&
          attrs.default_acl.low == UID_$NIL.low &&
          attrs.obj_flags[ACL_ATTR_OBJ_TYPE] != 0)) {
        locked = (int8_t)0xFF;
        ML_$LOCK(ML_LOCK_ACL);
        slot = acl_$find_acl_slot(&attrs.default_acl, &cached, prot, &status);
        if (status != status_$ok) {
            goto out;
        }
    }

    /* 0x00E46C3A-0x00E46D18: owner, group, organisation */
    if (acl_$setids_one(prot->owner_rights, &prot->owner, prot->owner_ext[0],
                        set, &sids[0], &owner_ext[0], changed) ||
        acl_$setids_one(prot->group_rights, &prot->group, prot->owner_ext[1],
                        set, &sids[1], &owner_ext[1], changed) ||
        acl_$setids_one(prot->org_rights, &prot->org, prot->owner_ext[2],
                        set, &sids[2], &owner_ext[2], changed)) {
        status = status_$acl_no_right_to_set_subsystem_data;  /* 0x00E46D68 */
        goto out;
    }

    /* 0x00E46D1A-0x00E46D7C: the image's required-subsystem UID */
    if (slot == ACL_SETIDS_NO_SLOT) {
        sids[3] = UID_$NIL;
        goto out;
    }
    req = ACL_$DATA.acl_cache[slot].required_uid;   /* packed record */
    if (req.high == UID_$NIL.high && req.low == UID_$NIL.low) {
        sids[3] = UID_$NIL;
        goto out;
    }
    if (set < 0) {
        *changed = (int8_t)0xFF;
        sids[3] = req;
    } else if (sids[3].high != req.high || sids[3].low != req.low) {
        status = status_$acl_no_right_to_set_subsystem_data;
    }

out:
    /* 0x00E46D80-0x00E46D92 */
    if (locked < 0) {
        ML_$UNLOCK(ML_LOCK_ACL);
    }
    *status_ret = status;
}
